DELIMITER $$
CREATE PROCEDURE ficha_contar (IN p_cliente int, OUT p_total int)
BEGIN
    SELECT COUNT(*) INTO p_total FROM pedidos WHERE cliente_id = p_cliente;
END$$
DELIMITER ;
CALL ficha_contar(1, @total);
SELECT @total AS pedidos;
DROP PROCEDURE ficha_contar;

DELIMITER $$
CREATE FUNCTION ficha_con_impuesto (p_precio decimal(10, 2))
RETURNS decimal(12, 2)
DETERMINISTIC
BEGIN
    RETURN p_precio * 1.13;
END$$
DELIMITER ;
SELECT nombre, ficha_con_impuesto(precio) AS total FROM productos;
DROP FUNCTION ficha_con_impuesto;

DELIMITER $$
CREATE TRIGGER ficha_trg_precio
BEFORE INSERT ON productos
FOR EACH ROW
BEGIN
    IF NEW.precio < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El precio no puede ser negativo.';
    END IF;
END$$
DELIMITER ;
DROP TRIGGER ficha_trg_precio;

