DELIMITER $$
CREATE FUNCTION ficha_nivel (p_precio decimal(10, 2))
RETURNS varchar(10)
DETERMINISTIC
BEGIN
    IF p_precio > 50 THEN
        RETURN 'caro';
    END IF;
    RETURN 'barato';
END$$
DELIMITER ;
SELECT ficha_nivel(80) AS nivel;
DROP FUNCTION ficha_nivel;

DELIMITER $$
CREATE FUNCTION ficha_suma (p_hasta int)
RETURNS int
DETERMINISTIC
BEGIN
    DECLARE v_total int DEFAULT 0;
    DECLARE v_i int DEFAULT 1;
    WHILE v_i <= p_hasta DO
        SET v_total = v_total + v_i;
        SET v_i = v_i + 1;
    END WHILE;
    RETURN v_total;
END$$
DELIMITER ;
SELECT ficha_suma(4) AS suma;
DROP FUNCTION ficha_suma;

DELIMITER $$
CREATE PROCEDURE ficha_seguro ()
BEGIN
