    BEGIN
        ROLLBACK;
        SELECT 'Se deshizo todo' AS resultado;
    END;
    START TRANSACTION;
    INSERT INTO categorias (id, nombre) VALUES (1, 'repetida');
    COMMIT;
END$$
DELIMITER ;
CALL ficha_seguro();
