DELIMITER $$
CREATE PROCEDURE ficha_rechazar (p_valor int)
BEGIN
    IF p_valor < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El valor no puede ser negativo.';
    END IF;
END$$
DELIMITER ;
CALL ficha_rechazar(1);
DROP PROCEDURE ficha_rechazar;

DELIMITER $$
CREATE PROCEDURE ficha_recorrer ()
BEGIN
    DECLARE v_fin int DEFAULT 0;
    DECLARE v_precio decimal(10, 2);
    DECLARE v_total decimal(12, 2) DEFAULT 0;
    DECLARE c CURSOR FOR SELECT precio FROM productos;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin = 1;
    OPEN c;
    bucle: LOOP
        FETCH c INTO v_precio;
        IF v_fin = 1 THEN
            LEAVE bucle;
        END IF;
        SET v_total = v_total + v_precio;
    END LOOP;
    CLOSE c;
    SELECT v_total AS total;
END$$
DELIMITER ;
CALL ficha_recorrer();
DROP PROCEDURE ficha_recorrer;
